(()=>{"use strict";function medidaCtrl($scope,medidaSvc,commonSvc,tS){$scope.medidas=[],$scope.dataSearch={pageIndex:1,pageSize:10},$scope.totalRecords=0,$scope.recordsQuantity=[5,10,25,50],$scope.getMedidas=function(){try{showLoader(),$scope.medidas=[],medidaSvc.getAll($scope.dataSearch).then(response=>{hideLoader(),$scope.medidas=response,$scope.totalRecords=$scope.medidas.length>0?$scope.medidas[0].totalRecords:0}).catch(error=>{hideLoader(),console.log(error)})}catch(error){console.log(error),hideLoader()}},$scope.getMedidas(),$scope.pagechanged=()=>{$scope.getMedidas()},$scope.changePageSize=()=>{$scope.dataSearch.pageIndex=1,$scope.getMedidas()},$scope.exportTableToExcel=()=>{try{showLoader();const medidas=$scope.medidas.map(item=>({codigo:item.codigo,descripcion:item.descripcion}));commonSvc.exportTableToExcel({arr:medidas,fileName:"Medidas"})}catch(error){hideLoader(),console.log(error)}},$scope.resultModal=function(item){$scope.getMedidas()},$scope.delete=function(data){try{Swal.fire({icon:"warning",html:"<small>Esta seguro/a de eliminar esta Medida ahora?</small>",showConfirmButton:!0,confirmButtonText:"Si, eliminar",showCancelButton:!0,cancelButtonText:"No, cancelar",allowOutsideClick:!1}).then(result=>{result.isConfirmed&&(showLoader(),medidaSvc.delete(data.idMedida).then(response=>{hideLoader(),"0"==response.code&&tS.toastr("warning",response.message,response.titleSms),"1"==response.code&&(tS.toastr("success",response.message,response.titleSms),$scope.getMedidas())}).catch(error=>{hideLoader(),console.log(error)}))})}catch(error){hideLoader(),console.log(error)}}}app.controller("medidaCtrl",medidaCtrl),medidaCtrl.$inject=["$scope","medidaService","commonService","toastService"]})(window.angular);